def solve(data):
    chosen = {}
    for i, row in enumerate(data):
        key = row['id']
        if key not in chosen or row['time'] > chosen[key]['time'] or (row['time'] == chosen[key]['time'] and i > chosen[key]['index']):
            chosen[key] = dict(row)
            chosen[key]['index'] = i
    return [chosen[key] for key in sorted(chosen)]

